import re
import hashlib

def verify_user(user_id: str) -> bool:
    """Verifica que el user_id tenga formato alfanumérico válido y longitud adecuada."""
    if not isinstance(user_id, str):
        return False
    if not (6 <= len(user_id) <= 32):
        return False
    return bool(re.match(r'^[a-zA-Z0-9_-]+$', user_id))

import unittest
from src.verify_user import verify_user

class TestVerifyUser(unittest.TestCase):
    def test_valid_user(self):
        self.assertTrue(verify_user("mauricio_123"))
        self.assertTrue(verify_user("user-valid"))

    def test_invalid_length(self):
        self.assertFalse(verify_user("usr"))
        self.assertFalse(verify_user("a" * 33))

    def test_invalid_characters(self):
        self.assertFalse(verify_user("user@domain"))
        self.assertFalse(verify_user("user name"))

if __name__ == '__main__':
    unittest.main()

# fastwebmcp

[![npm](https://img.shields.io/npm/v/fastwebmcp)](https://www.npmjs.com/package/fastwebmcp)

FastMCP-style ergonomics for [WebMCP](https://webmcp.com): typed Zod builders over the browser's Imperative and Declarative APIs.

## Quick Start

```ts
import { z } from 'zod';
import { registerTool } from 'fastwebmcp';

registerTool({
  name: 'add_todo',
  description: 'Add a todo item to the list.',
  inputSchema: z.object({ text: z.string().min(1) }),
  execute: async ({ text }) => {
    return `Added: ${text}`;
  },
});
```

## Declarative API

```html
<form toolname="submit_support" tooldescription="Submit support ticket">
  <input name="subject" toolparamdescription="Ticket subject" />
  <button type="submit">Send</button>
</form>
```

export function registerTool(config: any) {
  if (typeof window !== 'undefined' && (window as any).document?.modelContext) {
    return (window as any).document.modelContext.registerTool(config);
  }
  console.warn('[fastwebmcp] document.modelContext not available. Running fallback mock.');
  return config;
}
